////////////////////////////////////////////////////////////////////////////////////////////////////
// L A B  implementations

inline lab::lab(const xyz& x) {
    *this = x.to_lab();
}

inline lab::lab(const rgb& rgb) : lab(xyz(rgb)) {
}

inline double lab::delta_e_cie1994(const lab& other) const noexcept {
    constexpr auto k1 = .045;
    constexpr auto k2 = .015;
    constexpr auto kc = 1.0;
    constexpr auto kh = 1.0;
    constexpr auto kl = 1.0;
    constexpr auto sl = 1.0;

    const auto c1 = sqrtz(a()*a() + b()*b());
    const auto c2 = sqrtz(other.a()*other.a() + other.b()*other.b());
    const auto sc = 1 + k1*c1;
    const auto sh = 1 + k2*c1;
    const auto delta_a = a() - other.a();
    const auto delta_b = b() - other.b();
    const auto delta_c = c1 - c2;
    const auto delta_h = sqrtz(delta_a*delta_a +  delta_b*delta_b -  delta_c*delta_c);
    const auto delta_l = l() - other.l();

    return sqrtz(
               square(delta_l/(kl*sl)) +
               square(delta_c/(kc*sc)) +
               square(delta_h/(kh*sh))
           );
}

inline double lab::delta_e_cie2000(const lab& other) const noexcept {
    // This CIE2000 code was generated by Grok

    constexpr double k_L = 1.0;
    constexpr double k_C = 1.0;
    constexpr double k_H = 1.0;
    constexpr double deg_to_rad = pi() / 180.0;
    constexpr double rad_to_deg = 180.0 / pi();
    constexpr double TWENTY_FIVE_POW_7 = 6103515625.0; // 25^7

    const auto L_bar = (l() + other.l()) * 0.5;

    // Compute chromas
    const auto C1 = sqrtz(a() * a() + b() * b());
    const auto C2 = sqrtz(other.a() * other.a() + other.b() * other.b());

    // Mean chroma
    const auto C_bar = (C1 + C2) * 0.5;

    // G factor
    const auto cb2 = C_bar * C_bar;
    const auto cb4 = cb2 * cb2;
    const auto C_bar7 = cb4 * cb2 * C_bar;
    const auto G = 0.5 * (1.0 - sqrtz(C_bar7 / (C_bar7 + TWENTY_FIVE_POW_7)));

    // Adjusted a's
    const auto one_plus_G = 1.0 + G;
    const auto a1_p = a() * one_plus_G;
    const auto a2_p = other.a() * one_plus_G;

    // Adjusted chromas
    const auto C1_p = sqrtz(a1_p * a1_p + b() * b());
    const auto C2_p = sqrtz(a2_p * a2_p + other.b() * other.b());

    // Mean adjusted chroma
    const auto C_bar_p = (C1_p + C2_p) * 0.5;

    // Hue angles
    auto h1_p = std::atan2(b(), a1_p) * rad_to_deg;

    if(h1_p < 0.0) {
        h1_p += 360.0;
    }

    auto h2_p = std::atan2(other.b(), a2_p) * rad_to_deg;

    if(h2_p < 0.0) {
        h2_p += 360.0;
    }

    // Delta h'
    auto delta_h_p = h2_p - h1_p;

    if(std::abs(delta_h_p) > 180.0) {
        delta_h_p += (h2_p <= h1_p) ? 360.0 : -360.0;
    }

    // Delta L', Delta C', Delta H'
    const auto delta_L_p = other.l() - l();
    const auto delta_C_p = C2_p - C1_p;
    const auto delta_H_p = 2.0 * sqrtz(C1_p * C2_p) * std::sin(delta_h_p * deg_to_rad * 0.5);

    // Mean hue
    auto H_bar_p = (h1_p + h2_p) * 0.5;

    if(std::abs(h1_p - h2_p) > 180.0) {
        H_bar_p += 180.0;
    }

    // T
    const auto T = 1.0 - 0.17 * std::cos((H_bar_p - 30.0) * deg_to_rad) +
                   0.24 * std::cos(2.0 * H_bar_p * deg_to_rad) +
                   0.32 * std::cos((3.0 * H_bar_p + 6.0) * deg_to_rad) -
                   0.20 * std::cos((4.0 * H_bar_p - 63.0) * deg_to_rad);

    // S_L, S_C, S_H
    const auto L_bar_minus_50_sq = (L_bar - 50.0) * (L_bar - 50.0);
    const auto S_L = 1.0 + (0.015 * L_bar_minus_50_sq) / sqrtz(20.0 + L_bar_minus_50_sq);
    const auto S_C = 1.0 + 0.045 * C_bar_p;
    const auto S_H = 1.0 + 0.015 * C_bar_p * T;

    // R_T
    const auto cp2 = C_bar_p * C_bar_p;
    const auto cp4 = cp2 * cp2;
    const auto C_bar_p7 = cp4 * cp2 * C_bar_p;
    const auto sin_term = std::sin(60.0 * deg_to_rad * std::exp(-square((H_bar_p - 275.0) / 25.0)));
    const auto R_T = -2.0 * sqrtz(C_bar_p7 / (C_bar_p7 + TWENTY_FIVE_POW_7)) * sin_term;

    // Final Delta E (reuse normalized deltas to avoid extra divisions)
    const auto dL = delta_L_p / (k_L * S_L);
    const auto dC = delta_C_p / (k_C * S_C);
    const auto dH = delta_H_p / (k_H * S_H);

    const auto term1 = square(dL);
    const auto term2 = square(dC);
    const auto term3 = square(dH);
    const auto term4 = R_T * dC * dH;

    return sqrtz(term1 + term2 + term3 + term4);
}


////////////////////////////////////////////////////////////////////////////////////////////////////
// o k L A B  implementations
inline oklab::oklab(const rgb& rgb_c) noexcept {
    const xyz xyz_c{rgb_c};
    data_ = xyz_to_oklab(xyz_c.data(), color_space().gamut().xyz_white(), color_space().gamut().d65());
}

inline rgb oklab::to_rgb() const noexcept {
    const auto t = oklab_to_xyz(data_, color_space().gamut().xyz_white(), color_space().gamut().d65());
    return rgb{xyz{t}};
}

inline double oklab::hcl_h() const noexcept {
    return mod1(std::atan2(b(), a())/(pi()*2));
}

inline double oklab::hcl_s() const noexcept {
    return sqrtz(square(a()) + square(b()));
}

inline point<double> oklab::hue_to_ab(double hcl_h) noexcept {
    const auto angle = hcl_h*pi()*2;
    return point<double> {std::cos(angle), std::sin(angle)};
}

inline oklab::hcl oklab::to_hcl() const noexcept {
    const auto h_ = mod1(std::atan2(b(), a())/(pi()*2));
    const auto c_ = sqrtz(a()*a() + b()*b());
    const auto l_ = l();
    return hcl{h_, c_, l_};
}

inline oklab oklab::from_hcl(const hcl& hcl_c) noexcept {
    const auto l_ = hcl_c.l();
    const auto angle = hcl_c.h()*pi()*2;
    const auto a_ = std::cos(angle)*hcl_c.c();
    const auto b_ = std::sin(angle)*hcl_c.c();
    return oklab{l_, a_, b_};
}

inline oklab::hcl::hcl(const oklab& oklab_c) noexcept : data_(oklab_c.to_hcl().data()) {
}

inline bool oklab::in_gamut() const noexcept {
    return to_rgb().in_gamut();
}

